<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useLabSession } from '../session'
import { coreSceneAdapter,type SceneWorkbenchAdapter } from '../sceneAdapter'
import { childrenOf,nodeById,nodePath,nodeVisible,parentOptions,kindLabels,type SceneNode } from '../sceneGraph'
const props=defineProps<{adapter?:SceneWorkbenchAdapter}>(),lab=props.adapter??coreSceneAdapter(useLabSession()),tab=ref<'tree'|'info'>('tree'),expanded=ref<string[]>(['factory','area-preprocess','area-pyrolysis','area-utilities','workshop-monitoring']),name=ref(''),parent=ref('')
const selected=computed(()=>nodeById(lab.sceneLayout,lab.sceneView.selectedId)!)
watch(()=>[selected.value.id,selected.value.name,selected.value.parentId],()=>{name.value=selected.value.name;parent.value=selected.value.parentId??''},{immediate:true})
const rows=computed(()=>{const result:{node:SceneNode;depth:number}[]=[];const walk=(id:string,depth:number)=>{const n=nodeById(lab.sceneLayout,id);if(!n)return;result.push({node:n,depth});if(expanded.value.includes(id))childrenOf(lab.sceneLayout,id).forEach(c=>walk(c.id,depth+1))};walk('factory',0);return result})
watch(()=>lab.sceneView.selectedId,id=>{for(const n of nodePath(lab.sceneLayout,id).slice(0,-1))if(!expanded.value.includes(n.id))expanded.value.push(n.id)},{immediate:true})
const path=computed(()=>nodePath(lab.sceneLayout,selected.value.id).map(n=>n.name).join(' / '))
const binding=computed(()=>selected.value.assetId?lab.modelInfo(selected.value.assetId):null)
const currentPath=computed(()=>lab.sceneLayout.nodes.some(n=>n.assetId&&nodePath(lab.sceneLayout,n.id).some(p=>p.id===selected.value.id)))
function expand(id:string){expanded.value=expanded.value.includes(id)?expanded.value.filter(x=>x!==id):[...expanded.value,id]}
function visibility(node:SceneNode){if(!nodeVisible(lab.sceneLayout,node.id,lab.sceneView))lab.revealSceneNode(node.id);else lab.toggleSceneNode(node.id)}
function key(event:KeyboardEvent,id:string){if(event.key==='ArrowRight'){event.preventDefault();if(!expanded.value.includes(id))expanded.value.push(id)}else if(event.key==='ArrowLeft'){event.preventDefault();expanded.value=expanded.value.filter(x=>x!==id)}else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const buttons=Array.from((event.currentTarget as HTMLElement).closest('[role="tree"]')!.querySelectorAll<HTMLButtonElement>('.scene-node-select'));const index=buttons.indexOf(event.currentTarget as HTMLButtonElement);buttons[Math.min(buttons.length-1,Math.max(0,index+(event.key==='ArrowDown'?1:-1)))]?.focus()}}
</script>
<template><aside class="scene-tree-panel" aria-label="三维内部场景层级"><div class="scene-panel-tabs"><button :class="{active:tab==='tree'}" @click="tab='tree'">场景层级</button><button :class="{active:tab==='info'}" @click="tab='info'">模型信息</button></div><div v-if="tab==='tree'" class="scene-tree-scroll" role="tree" aria-label="工厂区域车间设备树"><div v-for="row in rows" :key="row.node.id" role="treeitem" :aria-level="row.depth+1" :aria-selected="lab.sceneView.selectedId===row.node.id" :class="['scene-node-row',{selected:lab.sceneView.selectedId===row.node.id,muted:!nodeVisible(lab.sceneLayout,row.node.id,lab.sceneView)}]" :style="{'--depth':row.depth}"><button class="node-expand" :aria-label="(expanded.includes(row.node.id)?'折叠':'展开')+row.node.name" :aria-expanded="expanded.includes(row.node.id)" :disabled="!childrenOf(lab.sceneLayout,row.node.id).length" @click="expand(row.node.id)">{{ childrenOf(lab.sceneLayout,row.node.id).length?(expanded.includes(row.node.id)?'▾':'▸'):'·' }}</button><button class="scene-node-select" :title="row.node.name" @click="lab.selectSceneNode(row.node.id,'tree')" @dblclick="lab.enterSceneNode(row.node.id)" @keydown.enter.prevent="lab.enterSceneNode(row.node.id)" @keydown="key($event,row.node.id)">{{ row.node.name }}</button><button class="scene-node-eye" :aria-label="(nodeVisible(lab.sceneLayout,row.node.id,lab.sceneView)?'隐藏':'显示')+row.node.name" :disabled="row.node.kind==='factory'" @click="visibility(row.node)">{{ nodeVisible(lab.sceneLayout,row.node.id,lab.sceneView)?'◉':'○' }}</button><button class="scene-node-enter" :aria-label="(row.node.kind==='equipment'?'定位':'进入')+row.node.name" @click="lab.enterSceneNode(row.node.id)">↗</button></div></div><div v-else class="scene-info-scroll"><span class="scene-type-label">{{ kindLabels[selected.kind] }} · 场景修订 {{ lab.sceneLayout.revision }}</span><p class="scene-info-path">{{ path }}</p><dl><dt>稳定模型ID</dt><dd>{{ selected.id }}</dd><dt>模型来源</dt><dd>程序化教学示意<br>{{ selected.modelRef }}</dd><template v-if="selected.assetId"><dt>实验模型键</dt><dd>{{ selected.assetId }}</dd><dt>实际关联资产</dt><dd>{{ binding?.asset ? binding.asset.code+' · '+binding.asset.name : '未绑定' }}</dd></template></dl><p class="scene-context-note">{{ currentPath?lab.contextNote:'教学示意模型，相关实验待建设。' }}</p><div class="scene-info-buttons"><button @click="lab.enterSceneNode(selected.id)">进入 / 定位</button><button @click="lab.isolateSceneNode(selected.id)">隔离显示</button><button @click="lab.restoreSceneVisibility">恢复显示</button></div><details><summary>修改名称与归属</summary><fieldset class="scene-edit-fields" :disabled="!lab.canEdit"><label>场景显示名称<input v-model="name" aria-label="场景显示名称" maxlength="40" /></label><label>所属层级<select v-model="parent" aria-label="所属层级" :disabled="selected.kind==='factory'"><option v-if="selected.kind==='factory'" value="">固定根节点</option><option v-for="p in parentOptions(lab.sceneLayout,selected)" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><button class="scene-edit-save" @click="lab.editSceneNode(selected.id,name,parent||null)">保存场景调整</button></fieldset><p>{{ lab.editReason }}</p></details></div><div class="scene-panel-footer"><button @click="tab=tab==='tree'?'info':'tree'">{{ tab==='tree'?'查看所选模型信息':'返回场景层级' }}</button><button aria-label="恢复全部模型显示" @click="lab.restoreSceneVisibility">全部显示</button></div></aside></template>
